/**
 * Before the King
 * ---------------
 * Nehemiah asks the king for letters and timber, and the king grants what he asks, and he goes to the governors beyond the river. Stage: a royal throne room at noon, a cupbearer standing, a king with his sceptre, a scroll of letters; the favour of a monarch, a journey beginning.
 *
 * Palette 0x2d1a0e → 0x060402 · light: dusk · hero: scroll
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./nehemiah-kit.js.
 */

import { THREE, createScene, water, column, throne, house, scroll, person } from './nehemiah-kit.js';

const BG = 0x2d1a0e;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 2898093469, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* river: animated water between grassy banks */
    water(W, group, 260, 26, -0.4, 0x020101, 0x070502);
    W.ground(260, 95, 0, 60, 0x060402, { amp: 0.5, j: 0.3, flat: 24, fz: 54 });
    W.ground(260, 95, 0, -64, 0x050302, { amp: 0.6, j: 0.3, flat: 24, fz: -58 });
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x030201), [0, -0.05, 12.6]);
    W.add(group, W.G('box', 260, 0.3, 4), W.mat(0x030201), [0, -0.05, -14.6]);

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0x060402, { band: 0x22140b });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x1d1109 });

    /* house: mud-brick walls, flat roof, door */
    house(W, group, 19, 0, -17, 1.0 + W.r() * 0.3, { mud: 0x060402 });

    /* hero: the scroll */
    scroll(W, group, 0, 0.9, 11, 1.2, { ry: 0.5 });
    W.disc([0, 4, 1], 4, 0x3b2212, 0.3);

    /* figures */
    person(W, group, [-5, 0, 16], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, bend: 0.02, ry: 0.52, s: 1.04 });

    return W.finish();
}

export default { build };
